effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec4 original = fxPortSample(inputImg.texture, uv);
    float verticalCycles = 5.4 * exp2(uControl2);
    float horizontalCycles = 5.4 * exp2(uControl3);
    float verticalAmplitude = 0.05 * exp2(uControl4);
    float horizontalAmplitude = 0.05 * exp2(uControl5);
    float verticalPhase = 0.5 * uControl6;
    float horizontalPhase = 0.5 * uControl7;
    vec2 sourceUv = uv + vec2(
        horizontalAmplitude * sin(6.28318530718 * (horizontalCycles * uv.y + horizontalPhase)),
        verticalAmplitude * sin(6.28318530718 * (verticalCycles * uv.x + verticalPhase))
    );
    vec4 warped = fxPortSample(inputImg.texture, clamp(sourceUv, 0.0, 1.0));
    fxPortOutput = clamp(mix(original, warped, clamp(uControl1, 0.0, 1.0)), 0.0, 1.0);
}

void main() {
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
